using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// End-to-end conformance test for a real aomenc-encoded 128x128 all-intra clip that enables loop
/// restoration (self-guided, radius-2) on the luma plane. It exercises the per-superblock
/// restoration-info parsing, the intra transform-size neighbour context, directional prediction with
/// smooth-neighbour edge filtering, and the full reconstruction, deblocking, CDEF and loop-restoration
/// pipeline. The reconstructed planes are compared against the dav1d reference (full pipeline including
/// loop restoration); the match is bit-exact across all three planes.
/// </summary>
public class Av1LoopRestorationClipDecodeTests
{
    private const string IvfBase64 = "";
    private const string ReferenceLumaBase64 = "";
    private const string ReferenceChromaUBase64 = "";
    private const string ReferenceChromaVBase64 = "";

    [Fact]
    public void Decode_LoopRestorationClip_MatchesDav1d()
    {
        using MemoryStream stream = new(Convert.FromBase64String(IvfBase64));
        Av1IntraTileDecoder decoder = Av1DecoderCore.DecodeFirstFrame(stream);

        Assert.Equal(Convert.FromBase64String(ReferenceLumaBase64), decoder.Luma.Samples);
        Assert.Equal(Convert.FromBase64String(ReferenceChromaUBase64), decoder.ChromaU.Samples);
        Assert.Equal(Convert.FromBase64String(ReferenceChromaVBase64), decoder.ChromaV.Samples);
    }
}
